"""Reproduce original non-packaging category illustrations; no third-party artwork."""
from pathlib import Path
import math
root=Path(__file__).resolve().parents[1]/'theme/glowwise/assets/art'
root.mkdir(parents=True,exist_ok=True)
defs='''<defs><radialGradient id="light" cx="30%" cy="25%"><stop stop-color="#fffdf8"/><stop offset=".6" stop-color="#e5b798"/><stop offset="1" stop-color="#b88667"/></radialGradient><linearGradient id="teal" x2="1" y2="1"><stop stop-color="#4e7770"/><stop offset="1" stop-color="#123f3f"/></linearGradient><linearGradient id="cream" x2="1" y2="1"><stop stop-color="#fffdf8"/><stop offset="1" stop-color="#c5cdb9"/></linearGradient><filter id="shadow" x="-40%" y="-40%" width="180%" height="180%"><feGaussianBlur stdDeviation="16"/></filter></defs>'''
def write(name,body,view='0 0 640 640'):
 (root/(name+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}" role="img"><title>Original Glowwise {name.replace("-"," ")} illustration</title>{defs}{body}</svg>\n',encoding='utf-8')
base='<ellipse cx="330" cy="520" rx="135" ry="20" fill="#123f3f" opacity=".13" filter="url(#shadow)"/>'
spark='<path d="M495 122q0 28-28 28q28 0 28 28q0-28 28-28q-28 0-28-28Z" fill="#123f3f"/><circle cx="120" cy="380" r="4" fill="#123f3f"/>'
write('skincare',base+spark+'<circle cx="315" cy="290" r="142" fill="url(#cream)"/><circle cx="315" cy="290" r="118" fill="none" stroke="#123f3f" stroke-opacity=".25"/><circle cx="330" cy="270" r="74" fill="url(#light)"/><path d="M130 430Q270 370 410 428T550 440" fill="none" stroke="#123f3f" stroke-width="2"/><path d="M150 450Q270 390 410 448T530 460" fill="none" stroke="#123f3f" stroke-opacity=".3"/><path d="M220 140l-18-20m260 205l24 6m-177-213v-24" stroke="#123f3f" stroke-width="2"/>')
write('haircare',base+spark+'<path d="M130 460C130 240 540 175 490 335C450 465 190 360 230 235C263 134 400 173 375 284C350 399 100 389 180 485" fill="none" stroke="url(#teal)" stroke-width="42" stroke-linecap="round"/><path d="M132 448C150 247 523 193 480 326C431 467 180 335 243 229C300 147 395 203 363 286" fill="none" stroke="#ecded0" stroke-opacity=".45" stroke-width="3"/><ellipse cx="400" cy="450" rx="55" ry="43" fill="url(#light)"/>')
write('bodycare',base+spark+'<path d="M185 435C155 316 230 133 358 173C491 214 481 350 436 435Z" fill="url(#cream)"/><path d="M228 445C258 231 488 273 454 401C421 529 260 479 228 445Z" fill="url(#light)"/><path d="M240 219Q286 263 354 272M242 242Q291 286 350 297M261 392Q322 376 394 402" fill="none" stroke="#123f3f" stroke-opacity=".22" stroke-width="2"/><path d="M183 449q102 49 255 0" fill="none" stroke="#123f3f" stroke-width="1.5"/>')
petals=''.join(f'<ellipse cx="320" cy="236" rx="62" ry="122" transform="rotate({i*60} 320 320)" fill="{["url(#cream)","url(#light)"][i%2]}" opacity=".86"/>' for i in range(6))
write('fragrance',base+spark+petals+'<circle cx="320" cy="320" r="42" fill="url(#teal)"/><circle cx="315" cy="312" r="25" fill="none" stroke="#f7f4ec" stroke-opacity=".3"/><path d="M140 490Q320 400 500 490" fill="none" stroke="#123f3f" stroke-width="1.5"/>')
write('beard-grooming',base+spark+'<path d="M315 120C272 200 195 285 206 365C221 478 419 478 435 365C446 285 358 200 315 120Z" fill="url(#teal)"/><path d="M300 189C256 265 240 300 247 342" fill="none" stroke="#f7f4ec" stroke-opacity=".45" stroke-width="4" stroke-linecap="round"/><path d="M325 477q-72-52-26-98q61-35 89 27q-4 64-63 71Z" fill="url(#light)"/><path d="M148 275q-48 18-3 94q47-31 3-94Z" fill="url(#cream)"/><path d="M325 446q26-18 35-41" fill="none" stroke="#123f3f" stroke-opacity=".35" stroke-width="2"/>')
rails=''.join(f'<path d="M{200+i*21} 195v245" stroke="{["#123f3f","#60817a"][i%2]}" stroke-width="13" stroke-linecap="round"/>' for i in range(12))
write('grooming-tools',base+spark+'<circle cx="320" cy="320" r="158" fill="url(#cream)"/>'+rails+'<path d="M170 355L470 279" stroke="#e5b798" stroke-width="38"/><path d="M170 355L470 279" stroke="#fffdf8" stroke-opacity=".55" stroke-width="2"/><circle cx="480" cy="450" r="40" fill="url(#teal)"/>')
world='<circle cx="450" cy="450" r="342" fill="#e8e8da"/><circle cx="450" cy="450" r="300" fill="none" stroke="#123f3f" stroke-opacity=".2"/><circle cx="450" cy="450" r="240" fill="none" stroke="#123f3f" stroke-opacity=".3" stroke-dasharray="2 12"/><ellipse cx="450" cy="450" rx="330" ry="150" fill="none" stroke="#123f3f" stroke-opacity=".2" transform="rotate(-35 450 450)"/><ellipse cx="450" cy="450" rx="290" ry="220" fill="none" stroke="#123f3f" stroke-opacity=".15" transform="rotate(35 450 450)"/><path d="M450 200L510 390L700 450L510 510L450 700L390 510L200 450L390 390Z" fill="url(#cream)"/><path d="M450 200L450 450L700 450L510 390Z" fill="#f7f4ec" opacity=".7"/><circle cx="450" cy="450" r="122" fill="#f7f4ec" stroke="#123f3f" stroke-opacity=".15"/>'
for i,(x,y,r) in enumerate([(265,180,58),(725,345,64),(683,680,52),(358,767,70),(120,525,47),(730,180,28)]):world+=f'<circle cx="{x}" cy="{y}" r="{r}" fill="{["url(#light)","url(#teal)","url(#cream)"][i%3]}"/>'
world+='<path d="M170 180q0 20-20 20q20 0 20 20q0-20 20-20q-20 0-20-20Zm540 480q0 26-26 26q26 0 26 26q0-26 26-26q-26 0-26-26Z" fill="#123f3f"/>'
write('compass-world',world,'0 0 900 900')
write('finder-compass','<circle cx="350" cy="350" r="245" fill="none" stroke="#f7f4ec" stroke-opacity=".25"/><circle cx="350" cy="350" r="185" fill="none" stroke="#f7f4ec" stroke-opacity=".3" stroke-dasharray="2 10"/><path d="M350 113L408 292L587 350L408 408L350 587L292 408L113 350L292 292Z" fill="url(#light)"/><path d="M350 113L350 350L587 350L408 292Z" fill="#f7f4ec" opacity=".6"/><circle cx="350" cy="350" r="37" fill="#123f3f"/><circle cx="350" cy="350" r="17" fill="#e5b798"/><circle cx="160" cy="195" r="28" fill="url(#cream)"/><circle cx="553" cy="509" r="36" fill="url(#light)"/>','0 0 700 700')
print('Generated 8 original SVG illustrations.')
